  "print.howBluetoothBody": "اس صفحے سے، ڈیسک ٹاپ Chrome یا Edge پر اور Android Chrome پر: اپنا لیبل پرنٹر منتخب کریں اور لیبلز براہ راست اس پر چلے جاتے ہیں۔ یہ iOS Safari میں کام نہیں کرتا — iPhone پر Bluetooth پرنٹنگ موبائل ایپ کے ساتھ آتی ہے۔ جو پرنٹر صرف Zebra ZPL یا Brother کی اپنی زبان بولتا ہے وہ اس صفحے کے بھیجے گئے لیبلز نہیں سمجھے گا؛ اسے کام کرتا کہنے سے پہلے اصل پرنٹرز کے خلاف جانچا جاتا ہے۔",
