  "print.howWifiBody": "پرنٹر کو اپنی دکان کے Wi-Fi پر انسٹال کریں، پھر پرنٹ بٹن استعمال کریں — یہ دکان کے نیٹ ورک پر، اس کمپیوٹر پر انسٹال شدہ پرنٹر کے ذریعے پرنٹ کرتا ہے۔ iPhone پر AirPrint پہلے سے موجود ہے: اسی Wi-Fi پر موجود AirPrint پرنٹر پرنٹ شیٹ میں بس ظاہر ہو جاتا ہے، نہ تار درکار نہ ایپ، اور ایپ کو AirPrint کے لیے مخصوص کوڈ کی ضرورت نہیں۔ پرنٹر کو AirPrint کی حمایت کرنی چاہیے (بیشتر نئے کرتے ہیں) اور فون اور پرنٹر کو اسی Wi-Fi پر ہونا چاہیے۔",
