  "staff.access.pendingBody": "اس کاروبار میں آپ کی ای میل کے لیے ایک دعوت ہے جو ابھی فعال نہیں ہوئی۔ مالک سے کہیں کہ آپ کے عملے کی حالت فعال کر دے۔ تب تک یہاں کچھ نظر نہیں آئے گا۔",
