  "settings.security.changeEmailDesc": "اپنے اکاؤنٹ کو نئی ای میل پر منتقل کریں۔ آپ کی دکان، انوینٹری، ٹیم اور تاریخ اس کے ساتھ منتقل ہو جاتی ہے — اور کوئی نئی مفت آزمائش شروع نہیں ہوتی۔ ہر دوسرا سائن ان شدہ آلہ سائن آؤٹ ہو جاتا ہے۔",
