  "workforce.tab.rewards": "انعامات",
  "training.lessons.mgr-give-rewards.step1": "ورک فورس کھولیں اور انعامات پر ٹیپ کریں۔ ٹیم ممبر منتخب کریں، پھر قسم: اسٹور میں فیصد رعایت، ایک گفٹ کارڈ، یا کچھ اور جو آپ اپنے الفاظ میں بیان کریں۔",
  "training.lessons.mgr-give-rewards.step2": "انعام کو ایک مختصر نام دیں اور اگر چاہیں تو نوٹ دیں۔ اس شخص کو فوراً گھنٹی ملتی ہے، اور انعام اس کے اپنے کوڈ کے ساتھ اس کے میرے انعامات میں انتظار کرتا ہے۔",
  "training.lessons.mgr-give-rewards.step3": "حد، ڈیزائن کے مطابق: آپ صرف عملے کو انعام دیتے ہیں۔ آپ خود کو یا کسی دوسرے مینیجر کو انعام نہیں دے سکتے — مینیجر کو انعام دینا مالک کا فیصلہ ہے، اور ایپ اسے صاف انکار کرے گی۔",
  "training.lessons.mgr-give-rewards.step4": "ٹل پر، وہ کوڈ لکھیں جو ٹیم ممبر آپ کو دکھاتا ہے اور اسے استعمال شدہ نشان زد کریں — ہر کوڈ ایک بار کام کرتا ہے۔ اگر منصوبے بدل جائیں تو آپ اپنے دیے گئے انعام کو منسوخ کر سکتے ہیں؛ مالک کے تحائف مالک کے منسوخ کرنے کے لیے ہیں۔",
  "training.lessons.mgr-give-rewards.title": "اپنے عملے کو انعامات دینا",
  "training.lessons.owner-give-rewards.step1": "انعامات ورک فورس میں، انعامات ٹیب پر رہتے ہیں، اور وہ صرف Business پلان کے لیے ہیں — Essentials پر ٹیب ایک بند دروازہ دکھاتا ہے، تاکہ آپ کی ٹیم دیکھ سکے کہ بڑا پلان کیا رکھتا ہے۔",
  "training.lessons.owner-give-rewards.step2": "آپ ٹیم میں کسی کو بھی انعام دے سکتے ہیں — عملہ اور مینیجر یکساں۔ شخص منتخب کریں، پھر قسم: اسٹور میں فیصد رعایت (کوئی بھی فیصد جو آپ منتخب کریں)، کہیں کا بھی گفٹ کارڈ، یا کوئی ترغیب جو آپ اپنے الفاظ میں بیان کریں۔",
  "training.lessons.owner-give-rewards.step3": "انعام اپنے ایک بار کے کوڈ کے ساتھ اترتا ہے اور اس شخص کی گھنٹی بجاتا ہے۔ وہ ٹل پر کوڈ دکھاتے ہیں؛ مالک یا مینیجر اسے استعمال شدہ نشان زد کرنے کے لیے لکھتا ہے۔",
  "training.lessons.owner-give-rewards.step4": "پرنٹ شدہ یا شیئر شدہ انعام سلپ پر صرف آپ کے کاروبار کا نام ہوتا ہے — ایپ کا کبھی نہیں۔ یہ آپ کے اسٹور کا شکریہ ہے، اشتہار نہیں۔",
  "training.lessons.owner-give-rewards.title": "انعامات دینا (Business پلان)",
  "training.lessons.owner-rewards-oversight.step1": "آپ کا مینیجر بھی انعامات دے سکتا ہے — صرف عملے کو۔ ایپ مینیجر کے خود کو یا کسی دوسرے مینیجر کو انعام دینے سے انکار کرتی ہے؛ مینیجر کو انعام دینا ہمیشہ آپ کا فیصلہ ہے۔",
  "training.lessons.owner-rewards-oversight.step2": "آپ انعامات کی تاریخ میں کاروبار کا ہر انعام دیکھتے ہیں: کس نے دیا، کس کو ملا، اور آیا یہ تیار، استعمال شدہ یا منسوخ ہے۔ مینیجر صرف وہ انعامات دیکھتا ہے جو اس نے دیے اور جو اسے ملے۔",
  "training.lessons.owner-rewards-oversight.step3": "آپ کوئی بھی انعام منسوخ کر سکتے ہیں، بشمول وہ جو آپ کے مینیجر نے دیا۔ مینیجر اپنے تحائف منسوخ کر سکتا ہے، لیکن آپ کے کبھی نہیں۔",
  "training.lessons.owner-rewards-oversight.step4": "ہر کوڈ بالکل ایک بار کام کرتا ہے، اور منسوخ شدہ انعام کبھی استعمال نہیں ہو سکتا — تاریخ ہمیشہ دکھاتی ہے کہ انعام کس طرح ختم ہوا۔",
  "training.lessons.owner-rewards-oversight.title": "انعامات کی نگرانی: آپ کے مینیجر کی عطا",
  "training.lessons.staff-your-rewards.step1": "جب آپ کا مینیجر یا مالک آپ کو انعام دیتا ہے تو آپ کی گھنٹی بجتی ہے۔ ورک فورس کھولیں اور اسے میرے انعامات کے تحت دیکھنے کے لیے انعامات پر ٹیپ کریں۔",
  "training.lessons.staff-your-rewards.step2": "ہر انعام کا اپنا کوڈ ہوتا ہے۔ اسے اپنے پاس رکھیں — جو ٹل پر کوڈ دکھاتا ہے وہی انعام استعمال کرتا ہے۔",
  "training.lessons.staff-your-rewards.step3": "اسے استعمال کرنے کے لیے، خریدتے وقت کوڈ دکھائیں۔ ٹل پر موجود شخص اسے لکھتا ہے اور استعمال شدہ نشان زد کرتا ہے — ہر کوڈ بالکل ایک بار کام کرتا ہے۔",
  "training.lessons.staff-your-rewards.step4": "انعامات Business پلان کی دعوت ہیں۔ اگر آپ کا اسٹور Business پر نہیں ہے تو انعامات ٹیب اس کے بجائے بند دروازہ دکھاتا ہے — یہ پلان ہے، غلطی نہیں۔",
  "training.lessons.staff-your-rewards.title": "آپ کے انعامات: اپنا کوڈ تلاش کرنا اور اسے استعمال کرنا",
  "training.module.rewards": "انعامات اور ترغیبات",
