  "pos.square.help": "Square منسلک کریں اور ٹل پر ہر فروخت اپنے آئٹم یہاں خود ہی اسٹاک سے نکالتی ہے — دن کے اختتام پر کچھ لکھنے کی ضرورت نہیں۔",
