  "support.description": "کچھ خراب ہے، کچھ غلط لگتا ہے، یا شیئر کرنے کے لیے کوئی خیال؟ ہمیں یہاں بتائیں — آپ کا نوٹ سیدھا ایپ کے پیچھے ٹیم کے پاس جاتا ہے۔",
