  "support.sentBody": "ہم ہر رپورٹ پڑھتے ہیں۔ اگر ہمیں مزید تفصیل چاہیے ہو تو ہم آپ کے اکاؤنٹ ای میل پر لکھیں گے۔",
  "support.sentTitle": "شکریہ — آپ کی رپورٹ بھیج دی گئی۔",
