  "training.lessons.mgr-report-problem.step1": "آپ کی ٹیم ٹل پر کام کرتی ہے، جہاں مسائل سب سے پہلے ظاہر ہوتے ہیں۔ اگر ایپ آپ کی ٹیم میں کسی کے لیے خراب ہو یا عجیب برتاؤ کرے تو اسے اسی لمحے رپورٹ کیا جا سکتا ہے — ان کے ذریعے یا آپ کے ذریعے — سیٹنگز سے، مسئلہ رپورٹ کریں کے تحت۔",
  "training.lessons.mgr-report-problem.step2": "سادہ کہانی مانگیں: وہ کیا کر رہے تھے، انہیں کیا توقع تھی، اور اس کے بجائے کیا ہوا۔ اس کا ایک یا دو جملے بعد میں لکھی گئی کامل تفصیل سے زیادہ قیمتی ہیں۔",
  "training.lessons.mgr-report-problem.step3": "رپورٹ خود ہی صفحہ، اسٹور، بھیجنے والے کا کردار، پلان، ایپ زبان اور آلے کی قسم منسلک کرتی ہے؛ پروڈکٹس، اسٹاک اور فروخت کبھی منسلک نہیں ہوتیں۔ اسٹور کے اعداد کے بارے میں کچھ بھی رپورٹ کے ساتھ نہیں جاتا۔",
