  "training.lessons.mgr-report-problem.title": "جب آپ کی ٹیم کو رکاوٹ آئے: اسے رپورٹ کریں، اس کے گرد کام نہ کریں",
  "training.lessons.owner-report-problem.step1": "آپ کی سبسکرپشن میں ان لوگوں تک براہ راست لائن شامل ہے جو اس ایپ کو بناتے ہیں۔ سیٹنگز کھولیں اور مسئلہ رپورٹ کریں استعمال کریں — یہ ہر پلان پر ہے، آپ کے لیے اور آپ کی ٹیم کے ہر ممبر کے لیے۔",
  "training.lessons.owner-report-problem.step2": "اپنے الفاظ میں کہیں کہ کیا ہوا: آپ کیا کرنے کی کوشش کر رہے تھے، اور ایپ نے اس کے بجائے کیا کیا۔ فارم خود ہی درست کرنے کی تفصیلات — صفحہ، کاروبار، کردار، پلان، زبان اور آلہ — منسلک کرتا ہے؛ آپ کی پروڈکٹس، اسٹاک اور فروخت کبھی شامل نہیں ہوتیں۔",
