  "training.lessons.owner-report-problem.step4": "ایک استثنا: اگر آپ یا کوئی ٹیم ممبر اکاؤنٹ میں بالکل داخل نہیں ہو سکتا تو رپورٹ تیز ترین دروازہ نہیں ہے۔ اضافی چابیاں (سیٹنگز، سیکیورٹی اور اضافی چابیاں) اور سائن ان صفحے پر بازیابی دروازہ بالکل اسی کے لیے موجود ہیں۔",
  "training.lessons.owner-report-problem.title": "ایک مسئلہ رپورٹ کریں: ایپ ٹیم تک آپ کی براہ راست لائن",
  "training.lessons.report-problem.step1": "اگر ایپ میں کچھ خراب ہو، غلط لگے، یا بس عجیب محسوس ہو تو آپ کو اس کے ساتھ جینا نہیں پڑتا۔ سیٹنگز کھولیں اور مسئلہ رپورٹ کریں تلاش کریں — یہ ہر کسی کے لیے، ہر پلان پر موجود ہے۔",
  "training.lessons.report-problem.step2": "منتخب کریں کہ آپ کا نوٹ کس بارے میں ہے — کچھ خراب ہے، کچھ غلط لگتا ہے، ایک خیال، یا کچھ اور — پھر اپنے الفاظ میں لکھیں کہ کیا ہوا۔ اس وقت آپ کیا کر رہے تھے یہ سب سے زیادہ مدد کرتا ہے۔",
  "training.lessons.report-problem.step3": "آپ کا نوٹ خود ہی وہ صفحہ لے جاتا ہے جس پر آپ تھے، آپ کا اسٹور اور کردار، آپ کا پلان، آپ کی ایپ زبان، اور آپ کس قسم کا فون یا براؤزر استعمال کرتے ہیں — وہ تفصیلات جو مسئلہ تلاش کرنے میں مدد کرتی ہیں۔ یہ آپ کی پروڈکٹس، اسٹاک یا فروخت کبھی نہیں لے جاتا۔",
